        <section class="cart-shell"><div class="wrap" style="max-width:700px"><div class="auth-card"><div class="eyebrow">Customer account</div><h1>Create account</h1><p class="muted">Orders already placed with this email will automatically appear after sign in.</p><form method="post" action="{{ $accountRegisterUrl }}" class="field-grid">@csrf<div class="field"><label>First name</label><input name="first_name" value="{{ old('first_name') }}" autocomplete="given-name" required></div><div class="field"><label>Last name</label><input name="last_name" value="{{ old('last_name') }}" autocomplete="family-name" required></div><div class="field full"><label>Email</label><input type="email" name="email" value="{{ old('email') }}" autocomplete="email" required></div><div class="field full"><label>Previous order number</label><input name="order_number" value="{{ old('order_number') }}" placeholder="Verify this account with one of your orders" required></div><div class="field"><label>Password</label><input type="password" name="password" autocomplete="new-password" minlength="8" required></div><div class="field"><label>Confirm password</label><input type="password" name="password_confirmation" autocomplete="new-password" minlength="8" required></div><div class="field full"><button class="btn" type="submit">Create account</button></div></form><p class="muted" style="margin-bottom:0">Already registered? <a href="{{ $accountLoginUrl }}" style="font-weight:800;color:var(--c-primary)">Sign in</a>.</p></div></div></section>
